import{_ as n,o as s,c as e,a2 as i}from"./chunks/framework.EUByU7Iq.js";const _=JSON.parse('{"title":"第十四章 居住权","description":"","frontmatter":{"title":"第十四章 居住权","date":"2021-02-16T00:00:00.000Z","categories":["法律","民法典"],"tags":["法律","民法典"]},"headers":[],"relativePath":"blogs/CC/disanfenbian：yongyiwuquan（dishisizhang：jizhuquan）.md","filePath":"blogs/CC/第三分编：用益物权（第十四章：居住权）.md"}'),t={name:"blogs/CC/disanfenbian：yongyiwuquan（dishisizhang：jizhuquan）.md"};function r(l,a,p,o,d,h){return s(),e("div",null,[...a[0]||(a[0]=[i(`<h3 id="第三百六十六条" tabindex="-1">第三百六十六条 <a class="header-anchor" href="#第三百六十六条" aria-label="Permalink to &quot;第三百六十六条&quot;">​</a></h3><p>居住权人有权按照合同约定，对他人的住宅享有占有、使用的用益物权，以满足生活居住的需要。</p><h3 id="第三百六十七条" tabindex="-1">第三百六十七条 <a class="header-anchor" href="#第三百六十七条" aria-label="Permalink to &quot;第三百六十七条&quot;">​</a></h3><p>设立居住权，当事人应当采用书面形式订立居住权合同。 居住权合同一般包括下列条款：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>（一）当事人的姓名或者名称和住所；</span></span>
<span class="line"><span>（二）住宅的位置；</span></span>
<span class="line"><span>（三）居住的条件和要求；</span></span>
<span class="line"><span>（四）居住权期限；</span></span>
<span class="line"><span>（五）解决争议的方法。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="第三百六十八条" tabindex="-1">第三百六十八条 <a class="header-anchor" href="#第三百六十八条" aria-label="Permalink to &quot;第三百六十八条&quot;">​</a></h3><p>居住权无偿设立，但是当事人另有约定的除外。设立居住权的，应当向登记机构申请居住权登记。居住权自登记时设立。</p><h3 id="第三百六十九条" tabindex="-1">第三百六十九条 <a class="header-anchor" href="#第三百六十九条" aria-label="Permalink to &quot;第三百六十九条&quot;">​</a></h3><p>居住权不得转让、继承。设立居住权的住宅不得出租，但是当事人另有约定的除外。</p><h3 id="第三百七十条" tabindex="-1">第三百七十条 <a class="header-anchor" href="#第三百七十条" aria-label="Permalink to &quot;第三百七十条&quot;">​</a></h3><p>居住权期限届满或者居住权人死亡的，居住权消灭。居住权消灭的，应当及时办理注销登记。</p><h3 id="第三百七十一条" tabindex="-1">第三百七十一条 <a class="header-anchor" href="#第三百七十一条" aria-label="Permalink to &quot;第三百七十一条&quot;">​</a></h3><p>以遗嘱方式设立居住权的，参照适用本章的有关规定。</p>`,13)])])}const u=n(t,[["render",r]]);export{_ as __pageData,u as default};
